BEGIN;
DO $$
DECLARE own text; a uuid; b uuid; bot uuid; p uuid; q uuid; r uuid; t uuid; u uuid; v uuid; c uuid; d uuid; j jsonb; catalog jsonb; blocked boolean;
BEGIN
 SELECT m.auth_subject INTO own FROM public.st_members m JOIN public.st_member_roles mr ON mr.member_id=m.id WHERE mr.role_code='owner' LIMIT 1;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('workflow-fixture-a','workflow fixture A') RETURNING id INTO a;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('workflow-fixture-b','workflow fixture B') RETURNING id INTO b;
 INSERT INTO public.st_members(auth_subject,display_name) VALUES('workflow-fixture-bot','workflow fixture bot') RETURNING id INTO bot;
 INSERT INTO public.st_member_roles(member_id,role_code) VALUES(a,'contributor'),(b,'contributor'),(bot,'bot');
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-a',true);EXECUTE 'SET LOCAL ROLE authenticated';
 p:=public.st_create_project('workflow manual fixture','manual creator becomes lead');
 j:=public.st_board(p);IF NOT (j->>'can_manage')::boolean OR (j->'me'->>'owner')::boolean THEN RAISE EXCEPTION 'Formal member creation or scoped leadership';END IF;
 t:=public.st_create_task(p,'manual translate','','translate');
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-b',true);
 catalog:=public.st_work_catalog();IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog->'tasks') x WHERE x->>'id'=t::text AND x->>'kind'='translate') THEN RAISE EXCEPTION 'Global open catalog';END IF;
 blocked:=false;BEGIN PERFORM public.st_task_detail(t);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Unjoined member reads private delivery';END IF;
 PERFORM public.st_claim_task(t);j:=public.st_board(p);IF (j->>'can_manage')::boolean THEN RAISE EXCEPTION 'Joining manual project steals leadership';END IF;
 PERFORM set_config('request.jwt.claim.sub',own,true);
 j:=public.st_create_codex_project('workflow codex fixture｜00:00｜AI字幕初稿','','AI review','');q:=(j->>'project_id')::uuid;u:=(j->>'task_id')::uuid;
 v:=public.st_create_task(q,'AI translate coerced','','translate');
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-a',true);
 blocked:=false;BEGIN PERFORM public.st_create_codex_project('forged AI');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Member forges privileged Codex intake';END IF;
 catalog:=public.st_work_catalog();IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog->'projects') x WHERE x->>'id'=q::text AND x->>'lead_member_id' IS NULL) THEN RAISE EXCEPTION 'Unclaimed project missing';END IF;
 PERFORM public.st_claim_task(u);j:=public.st_board(q);IF NOT (j->>'can_manage')::boolean THEN RAISE EXCEPTION 'First task claimant not lead';END IF;
 PERFORM public.st_release_task(u);IF NOT (public.st_board(q)->>'can_manage')::boolean THEN RAISE EXCEPTION 'Release transfers leadership';END IF;
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-b',true);
 blocked:=false;BEGIN PERFORM public.st_claim_project(q);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Second claimant steals lead';END IF;
 c:=public.st_claim_task(u);IF public.st_claim_task(u)<>c THEN RAISE EXCEPTION 'Claim idempotency';END IF;
 IF (public.st_board(q)->>'can_manage')::boolean THEN RAISE EXCEPTION 'Later claimant became lead';END IF;
 PERFORM set_config('request.jwt.claim.sub',own,true);
 j:=public.st_create_codex_project('workflow explicit project claim｜00:00｜AI字幕初稿');r:=(j->>'project_id')::uuid;
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-b',true);PERFORM public.st_claim_project(r);IF NOT (public.st_board(r)->>'can_manage')::boolean THEN RAISE EXCEPTION 'Explicit project claim';END IF;
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-a',true);
 d:=public.st_create_task(p,'AI draft import classification','','translate');PERFORM public.st_submit(d,'AI draft text','codex','fixture','fixture');
 PERFORM set_config('request.jwt.claim.sub',own,true);PERFORM public.st_delete_project(r,'workflow explicit project claim｜00:00｜AI字幕初稿');
 catalog:=public.st_work_catalog();IF EXISTS(SELECT 1 FROM jsonb_array_elements(catalog->'projects') x WHERE x->>'id'=r::text) THEN RAISE EXCEPTION 'Deleted project advertised';END IF;
 PERFORM set_config('request.jwt.claim.sub','workflow-fixture-bot',true);
 blocked:=false;BEGIN PERFORM public.st_create_project('bot forged');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Bot can create member project';END IF;
 PERFORM set_config('request.jwt.claim.sub','workflow-unapproved',true);
 blocked:=false;BEGIN PERFORM public.st_work_catalog();EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Unapproved account reads catalog';END IF;
 blocked:=false;BEGIN PERFORM public.st_create_project('pending forged');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Unapproved account creates project';END IF;
 EXECUTE 'RESET ROLE';
 IF (SELECT lead_member_id FROM public.st_projects WHERE id=p)<>a OR (SELECT lead_member_id FROM public.st_projects WHERE id=q)<>a OR (SELECT lead_member_id FROM public.st_projects WHERE id=r)<>b THEN RAISE EXCEPTION 'Persisted leadership';END IF;
 IF (SELECT count(*) FROM public.st_project_members WHERE project_id=q AND role='lead')<>1 THEN RAISE EXCEPTION 'Multiple first leads';END IF;
 IF (SELECT kind FROM public.st_tasks WHERE id=t)<>'translate' OR EXISTS(SELECT 1 FROM public.st_tasks WHERE id IN(u,v,d) AND kind<>'proofread') THEN RAISE EXCEPTION 'AI proofreading classification';END IF;
 IF has_function_privilege('anon','public.st_work_catalog()','EXECUTE') THEN RAISE EXCEPTION 'Anonymous catalog';END IF;
END; $$;
SELECT 'PASS: formal-member project creation and scoped leadership; Codex first project/task claimant becomes sole lead; later claims and releases preserve lead; global category catalog; join on task claim; private delivery isolation; AI proofreading classification; unapproved/bot restrictions; deleted projects hidden. All fixtures rolled back.' AS workflow_verification;
ROLLBACK;
